SELECT budget_bucket, stddev_budget FROM (SELECT CASE WHEN budget >= 3708000 THEN 'high' WHEN budget >= 1486000 THEN 'mid' ELSE 'low' END budget_bucket, ROUND(STDDEV(budget), 2) stddev_budget FROM departments WHERE dept_name = 'Finance' GROUP BY CASE WHEN budget >= 3708000 THEN 'high' WHEN budget >= 1486000 THEN 'mid' ELSE 'low' END) agg WHERE stddev_budget >= 63 ORDER BY stddev_budget, budget_bucket DESC LIMIT 20;
